package buildtools

import "github.com/cmusatyalab/steeleagle/sdk/preprocess"

// CompileError represents an error generated by any part of the compile
// stack, from the overlayer to the actual compiler.
type CompileError struct {
	Err    error  // the underlying error
	File   string // the file the error originates from
	Decl   string // decl that created the error (used in the mission planner)
	LineNo uint32 // the line number the error originates from (optional)
}

// Error implements the error interface, so a *CompileError can be used
// anywhere a plain error is expected.
func (e *CompileError) Error() string {
	return e.Err.Error()
}

// Unwrap returns the underlying error, so errors.Is and errors.As can see
// past a CompileError to whatever it wraps.
func (e *CompileError) Unwrap() error {
	return e.Err
}

// CompileErrors converts preprocessing errors to compile errors, keeping
// the file and line each is attributed to.
func CompileErrors(errs []*preprocess.PreprocessError) []*CompileError {
	out := make([]*CompileError, 0, len(errs))
	for _, e := range errs {
		out = append(out, &CompileError{Err: e, File: e.File, LineNo: e.LineNo})
	}
	return out
}
